lic.current_user_has_identity_access(l.identity_id))))","roles":["selqiro_listing_final_writer_v1"],"using":"(EXISTS ( SELECT 1\n   FROM public.listings l\n  WHERE ((l.id = listing_images.listing_id) AND public.current_user_has_identity_access(l.identity_id))))","command":"*","relation":"public.listing_images","permissive":true},{"name":"final_writer_listings","check":"public.current_user_has_identity_access(identity_id)","roles":["selqiro_listing_final_writer_v1"],"using":"public.current_user_has_identity_access(identity_id)","command":"*","relation":"public.listings","permissive":true}]'::jsonb AS final_writer_policies,
